  "tb.hubClubs": "{n} klabu · juu: {team} ({pts} pts)",
  "tb.hubDesc": "Jedwali la ligi la kila kompetishen muundo wetu unakadiriisha, ikarejea mara mbili kwa siku karibu na utabiri wetu.",
  "tb.hubH1a": "Jedwali",
  "tb.hubH1b": "la ligi",
  "tb.hubLead": "Nafasi za kila ligi muundo wetu unakadiriisha, inayotokea kwa picha ya data sawa inayopatia utabiri na ikarejea mara mbili kwa siku. Jedwali kila moja linakaa karibu na zile mechi za ligi, ili uweze kuenda kutoka nafasi hadi bei kwa kubofya moja.",
  "tb.hubPre": "Klabu {n} · msimu bado haujaanza",
  "tb.hubSec": "Jedwali tunayofunika",
  "tb.hubSeoH": "Jedwali linakuambia kinachotokea — bei zinakuambia nini kinataka kuwa",
  "tb.hubSeoP": "Nafasi ni ukurasa uliosomwa zaidi katika mpira na uliosomwa kupita kiasi zaidi katika kamati. Nafasi huhurusu miezi ya matokeo, bahati iliyojumuishwa, na haisemi kitu chochote moja kwa moja juu ya dakika tisini ijayo. Muundo wetu unakataa kuiangalia, ukikadirisha klabu kwenye kiwango kilicho na muda-kupungua cha kufanya mabao na kupokea mabao, kisha kulinganisha odds za haki zinazosababishwa na bei nzuri zaidi inayopatikana. Mahali ambapo jedwali linapata kazi ni muktadha: kusukuma kumwita, kupiga kelele haba, vifo vya damu katika Mei — habari juu ya motisha ambayo hakuna muundo wa kiwango unaweza kuona.",
  "tb.hubTitle": "Jedwali za Ligi za Mpira — Nafasi za Kila Ligi Tunayofunika",
  "tb.leadFinal": "Msimamo wa mwisho kutokana na msimu uliyokompliti uliopita wa {name} — klabu {n}, mechi za klabu {p} zilizochezwa. Jedwali la msimu mpya linaanza kujaza na raundi ya kwanza ya matokeo.",
  "tb.leadLive": "Msimamo wa {name} wa sasa katika klabu {n}, likibadilishwa mara mbili kwa siku pamoja na data yetu ya oddz.",
  "tb.leagueTips": "Vidokezo vya ligi",
  "tb.livePages": "Ukurasa hai",
